js-mh-sort-versions.alternative:
const sortVersions = versions =>
  versions
    .map(version => ({ version, parts: version.split(".").map(Number) }))
    .sort((a, b) => {
      const length = Math.max(a.parts.length, b.parts.length);
      for (let i = 0; i < length; i++) {
        const difference = (a.parts[i] ?? 0) - (b.parts[i] ?? 0);
        if (difference) return difference;
      }
      return 0;
    })
    .map(({ version }) => version);

js-mh-sort-versions.wrong-cap:
const sortVersions = versions => {
  const compare = (a, b) => {
    const left = a.split(".").map(Number);
    const right = b.split(".").map(Number);
    // Walk the longer version; a part that is not there counts as 0.
    for (let i = 0; i < Math.max(left.length, right.length); i++) {
      const difference = (left[i] ?? 0) - (right[i] ?? 0);
      if (difference !== 0) return difference;
    }
    return 0; // equal: sort is stable, so they keep their order
  };
  return versions.slice(0,10).sort(compare);
};

js-mh2-table-of-contents.alternative:
const HEADING = /^(?<hashes>#{1,6}) +(?<title>[\s\S]*)$/;

const tableOfContents = markdown => {
  const root = { depth: 0, item: { children: [] } };
  const open = [root];
  let inCode = false;
  for (const line of markdown.split("\n")) {
    if (line.startsWith("```")) inCode = !inCode;
    const heading = !inCode && line.match(HEADING)?.groups;
    if (!heading) continue;
    const title = heading.title.trim();
    if (title === "") continue;
    const depth = heading.hashes.length;
    while (open.at(-1).depth >= depth) open.pop();
    const item = { title, children: [] };
    open.at(-1).item.children.push(item);
    open.push({ depth, item });
  }
  return root.item.children;
};

js-mh2-table-of-contents.wrong-empty-titles:
const tableOfContents = markdown => {
  const top = [];
  const open = []; // headings that can still take children, shallowest first
  let inCode = false;
  for (const line of markdown.split("\n")) {
    if (line.startsWith("```")) {
      inCode = !inCode; // a fence opens or closes a code block
      continue;
    }
    if (inCode) continue;
    // One to six #s and a space: seven #s and "#tag" do not match.
    const match = line.match(/^(#{1,6}) +(.+)$/);
    if (!match) continue;
    const depth = match[1].length;
    const item = { title: match[2].trim(), children: [] };
    // A heading closes every open heading at its own depth or deeper.
    while (open.length > 0 && open[open.length - 1].depth >= depth) open.pop();
    (open.length > 0 ? open[open.length - 1].item.children : top).push(item);
    open.push({ depth, item });
  }
  return top;
};

js-mh-paint-bucket.alternative:
const NEIGHBOURS = [[-1, 0], [1, 0], [0, -1], [0, 1]];

const paintBucket = (grid, row, col, colour) => {
  const copy = grid.map(cells => [...cells]);
  const from = copy[row][col];
  const paint = (r, c) => {
    if (copy[r]?.[c] !== from) return;
    copy[r][c] = colour;
    NEIGHBOURS.forEach(([dr, dc]) => paint(r + dr, c + dc));
  };
  if (from !== colour) paint(row, col);
  return copy;
};

js-mh-paint-bucket.wrong-empty-colour:
const paintBucket = (grid, row, col, colour) => {
  const copy = grid.map(cells => [...cells]); // new rows, so the caller's grid stays as it was
  if (!colour) return copy; const from = copy[row][col];
  // Painting a cell its own colour would never end: every cell stays "unpainted".
  if (from === colour) return copy;
  const paint = (r, c) => {
    if (r < 0 || r >= copy.length || c < 0 || c >= copy[r].length) return;
    if (copy[r][c] !== from) return;
    copy[r][c] = colour;
    paint(r - 1, c);
    paint(r + 1, c);
    paint(r, c - 1);
    paint(r, c + 1);
  };
  paint(row, col);
  return copy;
};

js-mh2-json-log.alternative:
const LEVELS = ["debug", "info", "warn", "error"];

const parseEntry = line => {
  try {
    const value = JSON.parse(line);
    return value && typeof value === "object" && !Array.isArray(value) && LEVELS.indexOf(value.level) !== -1 ? value : null;
  } catch {
    return null;
  }
};

const readLog = (text, minLevel) => {
  const read = text
    .split("\n")
    .map((line, index) => ({ number: index + 1, line }))
    .filter(({ line }) => line.trim())
    .map(({ number, line }) => ({ number, entry: parseEntry(line) }));
  return {
    entries: read
      .filter(({ entry }) => entry && LEVELS.indexOf(entry.level) >= LEVELS.indexOf(minLevel))
      .map(({ entry }) => entry),
    bad: read.filter(({ entry }) => !entry).map(({ number }) => number),
  };
};

js-mh2-json-log.wrong-trim-parse:
const LEVELS = ["debug", "info", "warn", "error"]; // least to most serious

const readLog = (text, minLevel) => {
  const parsed = [];
  const bad = [];
  text.split("\n").forEach((line, index) => {
    if (line.trim() === "") return; // skipped, but still counted for the line numbers
    try {
      const value = JSON.parse(line.trim()); // a trailing "\r" is only whitespace to JSON
      const isObject = value !== null && typeof value === "object" && !Array.isArray(value);
      // indexOf is -1 for anything that is not a level, "toString" included.
      if (isObject && LEVELS.indexOf(value.level) !== -1) parsed.push(value);
      else bad.push(index + 1);
    } catch {
      bad.push(index + 1);
    }
  });
  const floor = LEVELS.indexOf(minLevel);
  const entries = parsed.filter(entry => LEVELS.indexOf(entry.level) >= floor);
  return { entries, bad };
};

js-mh2-role-permissions.wrong-depth-cap:
const allowed = (roles, userRoles, permission) => {
  const visited = new Set(); // one per call, so a circle of roles comes to an end
  // "posts:*" covers every permission that starts with "posts:".
  const covers = rule => rule.endsWith(":*") && permission.startsWith(rule.slice(0, -1));
  const grants = (name, depth=0) => { if(depth>5)return false;
    // Only roles' own entries count: "constructor" is inherited, not a role.
    if (!Object.hasOwn(roles, name) || visited.has(name)) return false;
    visited.add(name);
    const role = roles[name];
    if (role.can.includes(permission) || role.can.some(covers)) return true;
    return (role.inherits ?? []).some(name=>grants(name,depth+1)); // the same question, one level down
  };
  return userRoles.some(name=>grants(name,0));
};
